s,d=req('POST','/rest/v1/ast_participantes',{'id':'pa3','ast_id':'hoy1','nombre':'Sin Firma','rut':'','firma':''},disp=D1); ok('Sin firma no se registra', s>=400)
s,d=req('POST','/rest/v1/ast_participantes',{'id':'pa4','ast_id':'hoy1','nombre':'No Acepta','rut':'','firma':'data:f','declaracion_aceptada':False},disp=D1); ok('Sin aceptar la declaración no se registra', s>=400)
