s,d=rpc('ast_emergencia',{'p_clave':CLAVE,'p_usuario':'lcortes','p_nombre':'','p_apellido':'','p_nueva':'Otra2026xx'},disp=D4)
ok('Después de 3 intentos fallidos el equipo queda bloqueado 15 minutos (incluso con la clave correcta)', d['ok']==False and 'Demasiados' in d['error'])
